import { useState } from "react";

export function App() {
  const [status, setStatus] = useState("idle");
  const [disabled] = useState(true);
  return (
    <div>
      <button
        data-testid="disabled-submit"
        onClick={() => {
          if (disabled) return;
          setStatus("fixed");
        }}
      >
        Disabled submit handler
      </button>
      <span data-testid="status">{status}</span>
    </div>
  );
}

